{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Repeated-run testing is undocumented."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "70% in one reported run",
          "reason": "One reported score does not establish consistency across runs."
        }
      ],
      "instrument_review": "The defined puzzle set and exact-grid scoring support interpreting the reported result for this evaluation. Repeatability is undocumented, limiting confidence in comparisons across runs; this is missing evidence, not demonstrated instability."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly rules out repeated-run testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "they ran the evaluation exactly once",
          "reason": "A single evaluation establishes neither stability nor instability across runs."
        }
      ],
      "instrument_review": "The puzzle scope and scoring rule are clear, but the documented absence of repetitions leaves score consistency unassessed. The 70% result describes one evaluation and provides limited support for repeatable comparisons."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "Repeated evaluations held the listed conditions constant."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The observed range meets the report's stability criterion of at most two percentage points."
        }
      ],
      "instrument_review": "Controlled repetitions support score consistency under the specified conditions and stated criterion. This strengthens interpretation of comparisons on these puzzles, but does not establish consistency for other systems, tasks, or conditions."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "The developers explicitly tested repeated evaluations under the same listed conditions."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The reported variation exceeds the defined stability limit of two percentage points."
        }
      ],
      "instrument_review": "The repetitions document a consistency problem under the report's own criterion. A single 70% score is insufficient for dependable comparisons given this variation; its cause and the full run results are not supplied."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation instructions do not document repeated-run testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The added instructions supply no evidence of score consistency."
        }
      ],
      "instrument_review": "Installation guidance documents setup steps, but does not resolve missing repeatability evidence. The score remains a single reported result for the specified puzzles and scoring rule."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A achieved the higher result on the evaluated puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The evidence does not establish comparative intelligence across domains."
        }
      ],
      "instrument_review": "The narrow intended use matches the tested content and reported comparison. Exact-grid scoring and fixed instructions clarify the comparison, while repeatability and other resource controls are unspecified. Cross-domain conclusions exceed the supplied evidence."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "The reported results show better puzzle performance by A."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "A broad intended use does not supply the missing cross-domain evidence."
        }
      ],
      "instrument_review": "The intended selection of greater general intelligence across domains is unsupported by testing confined to grid puzzles. The scores support a narrow performance comparison; broader task coverage and evidence connecting scores to the intended selection are missing. Repeatability and resource comparability are also unspecified."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "The initial scores alone do not establish improved real workshop decisions."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "The randomized trial supports better correctness with A, with a reported difference interval of 12 to 28 percentage points."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Correctness results do not establish an effect on an unmeasured safety outcome."
        }
      ],
      "instrument_review": "The preregistered randomized trial, new cases, blinded correctness checks, and reported uncertainty strengthen support for the intended workshop decision use. The evidence is limited to correctness in the studied workshop and conditions; it does not establish effects on time, safety, or other settings."
    }
  ],
  "closing_note": "No material instruction ambiguity was identified. Missing evidence was distinguished from explicit contradiction, and each case was assessed independently."
}
